test('invoiceTotals calculates VAT with different VAT rates', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [
      { sku: 'PRINT-A4', name: 'Printed flyer A4', qty: 100, unitPrice: 37, vatRate: 9, discountPercent: 0 },
      { sku: 'WORKSHOP-DAY', name: 'Brand workshop', qty: 1, unitPrice: 60000, vatRate: 0, discountPercent: 0 },
    ],
  };

  const totals = invoiceTotals(invoice);
  // Line 1: 100 * 37 = 3700, VAT = 3700 * 9 / 100 = 333
  // Line 2: 1 * 60000 = 60000, VAT = 60000 * 0 / 100 = 0
  // Subtotal: 63700
  // Total VAT: 333
  // Total: 63700 + 333 = 64033
  assert.equal(totals.subtotal, 63700);
  assert.equal(totals.vat, 333);
  assert.equal(totals.total, 64033);
});

test('invoiceTotals VAT is calculated per line and rounded', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [
      { sku: 'DES-HOUR', name: 'Design work (hour)', qty: 3, unitPrice: 8500, vatRate: 21, discountPercent: 0 },
    ],
  };

  const totals = invoiceTotals(invoice);
  // Line total: 3 * 8500 = 25500
  // VAT: 25500 * 21 / 100 = 5355
  // Total: 25500 + 5355 = 30855
  assert.equal(totals.subtotal, 25500);
  assert.equal(totals.vat, 5355);
  assert.equal(totals.total, 30855);
});

