test('createInvoice EOM handles end of month correctly for various months', () => {
  const cases = [
    { issueDate: '2026-01-15', expectedDue: '2026-01-31' },
    { issueDate: '2026-02-15', expectedDue: '2026-02-28' },
    { issueDate: '2024-02-15', expectedDue: '2024-02-29' }, // leap year
    { issueDate: '2026-04-20', expectedDue: '2026-04-30' },
  ];

  for (const { issueDate, expectedDue } of cases) {
    const result = createInvoice({
      customerId: 'C-001',
      issueDate,
      lines: [{ sku: 'DES-HOUR', qty: 5 }],
      terms: 'EOM',
    });

    assert.equal(result.ok, true, `failed for ${issueDate}`);
    assert.equal(result.value.dueDate, expectedDue, `failed for ${issueDate}`);
  }
});

